'use client';

import Link from 'next/link';
import { useEffect, useMemo, useState } from 'react';
import AppShell from '@/components/Navbar';
import { api } from '@/lib/api';
import { me } from '@/lib/auth';
import type { UserRole } from '@/config/navigation/types';

type ReadFilter = 'all' | 'unread' | 'read';

interface NotificationRow {
  id: number;
  type: string;
  reference_table: string;
  reference_id: number;
  message: string;
  is_read: boolean;
  created_at: string;
}

interface ApiEnvelope<T> {
  success: boolean;
  message: string;
  data: T;
}

type BackendRole = 'Admin' | 'Instructor' | 'Student';

const toUserRole = (role: BackendRole): UserRole =>
  role === 'Admin' ? 'admin' : role === 'Instructor' ? 'instructor' : 'student';

function timeAgo(ts: string): string {
  const diff = (Date.now() - new Date(ts).getTime()) / 1000;
  if (diff < 60) return `${Math.floor(diff)}s ago`;
  if (diff < 3600) return `${Math.floor(diff / 60)}m ago`;
  if (diff < 86400) return `${Math.floor(diff / 3600)}h ago`;
  return `${Math.floor(diff / 86400)}d ago`;
}

function buildHref(refTable: string, refId: number, role: UserRole): string {
  if (refTable === 'room_requests' || refTable === 'Room_Requests') {
    return role === 'admin' ? `/admin/requests/${refId}` : `/requests/${refId}`;
  }
  if (refTable === 'confirmed_schedule' || refTable === 'Confirmed_Schedule') {
    if (role === 'admin') return '/admin/schedule';
    if (role === 'student') return '/student/schedule';
    return '/instructor/schedule';
  }
  if (refTable === 'rooms' || refTable === 'Rooms') {
    return role === 'admin' ? '/admin/rooms' : '/instructor/rooms';
  }
  if (refTable === 'faculty_load_limits' || refTable === 'Faculty_Load_Limits') {
    return role === 'admin' ? '/admin/faculty-load' : '/instructor/faculty-load';
  }
  return '#';
}

export default function NotificationsPage() {
  const [role, setRole] = useState<UserRole>(() => {
    if (typeof document === 'undefined') return 'student';
    const roleCookie = document.cookie
      .split('; ')
      .find((c) => c.startsWith('role='))
      ?.split('=')[1];
    const decoded = roleCookie ? decodeURIComponent(roleCookie) : '';
    if (decoded === 'Admin') return 'admin';
    if (decoded === 'Instructor') return 'instructor';
    return 'student';
  });
  const [userName, setUserName] = useState('User');
  const [rows, setRows] = useState<NotificationRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
  const [typeFilter, setTypeFilter] = useState<string>('All');
  const [readFilter, setReadFilter] = useState<ReadFilter>('all');
  const [busyId, setBusyId] = useState<number | null>(null);
  const [markAllBusy, setMarkAllBusy] = useState(false);

  async function loadNotifications() {
    setLoading(true);
    setError('');
    try {
      const res = await api.get<ApiEnvelope<NotificationRow[]>>('/notifications');
      setRows(res.data ?? []);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Failed to load notifications.');
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    (async () => {
      try {
        const user = await me();
        setRole(toUserRole(user.role));
        setUserName(`${user.first_name} ${user.last_name}`);
      } catch {
        // middleware/API auth already handles unauthorized state
      }
    })();
    loadNotifications();
  }, []);

  const unreadCount = rows.filter((n) => !n.is_read).length;
  const presentTypes = [...new Set(rows.map((n) => n.type))];

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    return rows.filter((n) => {
      if (typeFilter !== 'All' && n.type !== typeFilter) return false;
      if (readFilter === 'unread' && n.is_read) return false;
      if (readFilter === 'read' && !n.is_read) return false;
      if (q && !(`${n.message} ${n.type}`.toLowerCase().includes(q))) return false;
      return true;
    });
  }, [rows, search, typeFilter, readFilter]);

  async function markRead(id: number) {
    setBusyId(id);
    try {
      await api.patch<ApiEnvelope<NotificationRow>>(`/notifications/${id}/read`, {});
      setRows((prev) => prev.map((n) => (n.id === id ? { ...n, is_read: true } : n)));
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Failed to mark notification as read.');
    } finally {
      setBusyId(null);
    }
  }

  async function markAllRead() {
    setMarkAllBusy(true);
    try {
      await api.patch<ApiEnvelope<null>>('/notifications/read-all', {});
      setRows((prev) => prev.map((n) => ({ ...n, is_read: true })));
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Failed to mark all as read.');
    } finally {
      setMarkAllBusy(false);
    }
  }

  return (
    <AppShell role={role} userName={userName} pageTitle="Notifications">
      <div className="max-w-3xl mx-auto">
        <div className="flex items-center justify-between gap-3 mb-4 flex-wrap">
          <h1 className="text-[20px] font-bold">Notifications</h1>
          {unreadCount > 0 && (
            <button className="btn btn-outline" onClick={markAllRead} disabled={markAllBusy}>
              {markAllBusy ? 'Marking...' : 'Mark all as read'}
            </button>
          )}
        </div>

        {error && <div className="card p-4 mb-4 text-sm" style={{ color: 'var(--color-error)' }}>{error}</div>}

        <div className="card card-body mb-4 flex flex-wrap gap-3 items-center">
          <input type="search" placeholder="Search notifications..." value={search} onChange={(e) => setSearch(e.target.value)} style={{ minWidth: 220 }} />
          <select value={readFilter} onChange={(e) => setReadFilter(e.target.value as ReadFilter)}>
            <option value="all">All</option>
            <option value="unread">Unread</option>
            <option value="read">Read</option>
          </select>
          <select value={typeFilter} onChange={(e) => setTypeFilter(e.target.value)}>
            <option value="All">All Types</option>
            {presentTypes.map((t) => <option key={t} value={t}>{t}</option>)}
          </select>
        </div>

        {loading ? (
          <div className="card p-6 text-sm" style={{ color: 'var(--color-text-muted)' }}>Loading notifications...</div>
        ) : filtered.length === 0 ? (
          <div className="card p-6 text-sm" style={{ color: 'var(--color-text-muted)' }}>No notifications found.</div>
        ) : (
          <div className="card overflow-hidden">
            {filtered.map((n) => (
              <div key={n.id} className="px-5 py-4 border-b last:border-0" style={{ borderColor: 'var(--color-border)', background: n.is_read ? 'transparent' : 'var(--color-primary-muted)' }}>
                <div className="flex items-start gap-3">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1 flex-wrap">
                      <span className="text-[11px] font-semibold px-2 py-0.5 rounded-full" style={{ background: 'var(--color-surface-2)', color: 'var(--color-text-secondary)' }}>
                        {n.type}
                      </span>
                      <span className="text-[11px]" style={{ color: 'var(--color-text-muted)' }}>{timeAgo(n.created_at)}</span>
                      {!n.is_read && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full" style={{ background: 'var(--color-primary)', color: '#fff' }}>New</span>}
                    </div>
                    <p className="text-[12.5px]">{n.message}</p>
                  </div>
                  <div className="flex gap-2 shrink-0">
                    {!n.is_read && (
                      <button className="btn btn-ghost" onClick={() => markRead(n.id)} disabled={busyId === n.id}>
                        {busyId === n.id ? '...' : 'Read'}
                      </button>
                    )}
                    <Link href={buildHref(n.reference_table, n.reference_id, role)} className="btn btn-ghost">View</Link>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </AppShell>
  );
}
